I was able to achieve a similar speedup by saving the performance start time from the constructor in a class property instead of calling `performance.now` in `_getTime` and combining the `if` statements like so (avoids second branch check):

```typescript
  constructor(opts: SpanOptions) {
    const now = Date.now();
    this._spanContext = opts.spanContext;
    this._performanceStartTime = performance.now();
    this._performanceOffset =
      now - (this._performanceStartTime + performance.timeOrigin);
    this.startTime = this._getTime(opts.startTime ?? now);
    /* [...] */
  }

  private _getTime(inp?: TimeInput): HrTime {
    if (typeof inp === 'number') {
      if (inp <= this._performanceStartTime) {
        // performance.now() timestamp — apply offset to convert to wall-clock
        return hrTime(inp + this._performanceOffset);
      }
      // Date.now() timestamp
      return millisToHrTime(inp);
    }
    /* [...] */
  }
```

